id_v1(limitations, 20)) IS TRUE))"},{"name":"sr2_source_sets_v1_f1","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, manifest_fingerprint) REFERENCES gov_repo.sr2_snapshots_v1(organisation_id, repository_id, snapshot_id, manifest_fingerprint)"},{"name":"sr2_source_sets_v1_f2","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, anchor_subject_id) REFERENCES gov_repo.sr2_subjects_v1(organisation_id, repository_id, snapshot_id, subject_id)"},{"name":"sr2_source_sets_v1_pkey","type":"p","definition":"PRIMARY KEY (organisation_id, repository_id, snapshot_id, source_set_id)"},{"name":"sr2_source_sets_v1_source_set_integrity","type":"t","definition":"TRIGGER DEFERRABLE INITIALLY DEFERRED"},{"name":"sr2_source_sets_v1_u1","type":"u","definition":"UNIQUE (organisation_id, repository_id, snapshot_id, source_set_id, scope_kind, anchor_subject_id)"},{"name":"sr2_subjects_v1_c1","type":"c","definition":"CHECK (((subject_family = ANY (ARRAY[''REPOSITORY_SNAPSHOT''::text, ''CODE_SYMBOL''::text, ''REPOSITORY_CHUNK''::text])) IS TRUE))"},{"name":"sr2_subjects_v1_c2","type":"c","definition":"CHECK (((((subject_family = ''REPOSITORY_SNAPSHOT''::text) AND (snapshot_manifest_fingerprint = source_fingerprint) AND (snapshot_manifest_fingerprint IS NOT NULL) AND (entry_id IS NULL) AND (chunk_locator_id IS NULL) AND (symbol_locator_id IS NULL)) OR ((subject_family = ''REPOSITORY_CHUNK''::text) AND (entry_id IS NOT NULL) AND (chunk_locator_id IS NOT NULL) AND (symbol_locator_id IS NULL) AND (snapshot_manifest_fingerprint IS NULL)) OR ((subject_family = ''CODE_SYMBOL''::text) AND (entry_id IS NOT NULL) AND (symbol_locator_id IS NOT NULL) AND (chunk_locator_id IS NULL) AND (snapshot_manifest_fingerprint IS NULL))) IS TRUE))"},{"name":"sr2_subjects_v1_c3","type":"c","definition":"CHECK (((subject_id = encode(sha256(convert_to(gov_repo.frame_identity((ARRAY[''GOVIA_SR2_SUBJECT_V1''::text] || ((((ARRAY[(organisation_id)::text, repository_id, snapshot_id, subject_family, source_fingerprint] || ARRAY[\nCASE\n    WHEN (entry_id IS NULL) THEN ''0''::text\n    ELSE ''1''::text\nEND, COALESCE(entry_id, ''''::text)]) || ARRAY[\nCASE\n    WHEN (snapshot_manifest_fingerprint IS NULL) THEN ''0''::text\n    ELSE ''1''::text\nEND, COALESCE(snapshot_manifest_fingerprint, ''''::text)]) || ARRAY[\nCASE\n    WHEN (chunk_locator_id IS NULL) THEN ''0''::text\n    ELSE ''1''::text\nEND, COALESCE(chunk_locator_id, ''''::text)]) || ARRAY[\nCASE\n    WHEN (symbol_locator_id IS NULL) THEN ''0''::text\n    ELSE ''1''::text\nEND, COALESCE(symbol_locator_id, ''''::text)]))), ''UTF8''::name)), ''hex''::text)) IS TRUE))"},{"name":"sr2_subjects_v1_f1","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, snapshot_manifest_fingerprint) REFERENCES gov_repo.sr2_snapshots_v1(organisation_id, repository_id, snapshot_id, manifest_fingerprint)"},{"name":"sr2_subjects_v1_f2","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, chunk_locator_id, entry_id, source_fingerprint) REFERENCES gov_repo.sr2_chunk_locators_v1(organisation_id, repository_id, snapshot_id, locator_id, entry_id, source_fingerprint)"},{"name":"sr2_subjects_v1_f3","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, symbol_locator_id, entry_id, source_fingerprint) REFERENCES gov_repo.sr2_symbol_locators_v1(organisation_id, repository_id, snapshot_id, locator_id, entry_id, source_fingerprint)"},{"name":"sr2_subjects_v1_pkey","type":"p","definition":"PRIMARY KEY (organisation_id, repository_id, snapshot_id, subject_id)"},{"name":"sr2_subjects_v1_u1","type":"u","definition":"UNIQUE (organisation_id, repository_id, snapshot_id, subject_id, entry_id, source_fingerprint)"},{"name":"sr2_subjects_v1_u2","type":"u","definition":"UNIQUE (organisation_id, repository_id, snapshot_id, subject_id, source_fingerprint)"},{"name":"sr2_summary_facets_v1_c1","type":"c","definition":"CHECK ((((facet_kind = ''TECHNICAL_SUMMARY''::text) AND (method_code = ''STRUCTURAL_SUMMARY''::text) AND (((octet_length(method_version) >= 1) AND (octet_length(method_version) <= 512)) AND (method_version ~ ''[^[:space:]]''::text) AND (lower(btrim(method_version)) <> ALL (ARRAY[''latest''::text, ''default''::text, ''unknown''::text]))) AND gov_repo.sr2_list_valid_v1(limitations, 20) AND (scope_kind = ANY (ARRAY[''PACKAGE_MEMBERS_V1''::text, ''MODULE_MEMBERS_V1''::text, ''SERVICE_MEMBERS_V1''::text, ''REPOSITORY_SELECTION_V1''::text]))) IS TRUE))"},{"name":"sr2_summary_facets_v1_c2","type":"c","definition":"CHECK (((((octet_length(summary_text) >= 1) AND (octet_length(summary_text) <= 1024)) AND (summary_text ~ ''[^[:space:]]''::text) AND (coverage = ''COMPLETE_DECLARED_SOURCE_SET_V1''::text)) IS TRUE))"},{"name":"sr2_summary_facets_v1_c3","type":"c","definition":"CHECK ((((item_key = encode(sha256(convert_to(gov_repo.frame_identity(ARRAY[''GOVIA_SR2_FACET_ITEM_V1''::text, (organisation_id)::text, repository_id, snapshot_id, subject_id, facet_kind, anchor_subject_id, grounding_set_id]), ''UTF8''::name)), ''hex''::text)) AND (payload_fingerprint = encode(sha256(convert_to(gov_repo.frame_identity((ARRAY[''GOVIA_SR2_FACET_PAYLOAD_V1''::text] || ((((ARRAY[facet_kind, item_key, grounding_set_id, scope_kind, anchor_subject_id, method_code, method_version] || ARRAY[(cardinality(limitations))::text]) || limitations) || ARRAY[summary_text]) || ARRAY[coverage]))), ''UTF8''::name)), ''hex''::text))) IS TRUE))"},{"name":"sr2_summary_facets_v1_f1","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, subject_id, projection_id, facet_kind) REFERENCES gov_repo.sr2_facet_collections_v1(organisation_id, repository_id, snapshot_id, subject_id, projection_id, facet_kind) DEFERRABLE INITIALLY DEFERRED"},{"name":"sr2_summary_facets_v1_f2","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, grounding_set_id, scope_kind, anchor_subject_id) REFERENCES gov_repo.sr2_source_sets_v1(organisation_id, repository_id, snapshot_id, source_set_id, scope_kind, anchor_subject_id)"},{"name":"sr2_summary_facets_v1_pkey","type":"p","definition":"PRIMARY KEY (organisation_id, repository_id, snapshot_id, subject_id, projection_id)"},{"name":"sr2_symbol_locators_v1_c1","type":"c","definition":"CHECK (((((octet_length(language_id) >= 1) AND (octet_length(language_id) <= 512)) AND (language_id ~ ''[^[:space:]]''::text) AND (lower(btrim(language_id)) <> ALL (ARRAY[''latest''::text, ''default''::text, ''unknown''::text])) AND (((octet_length(parser_id) >= 1) AND (octet_length(parser_id) <= 512)) AND (parser_id ~ ''[^[:space:]]''::text) AND (lower(btrim(parser_id)) <> ALL (ARRAY[''latest''::text, ''default''::text, ''unknown''::text]))) AND (((octet_length(parser_version) >= 1) AND (octet_length(parser_version) <= 512)) AND (parser_version ~ ''[^[:space:]]''::text) AND (lower(btrim(parser_version)) <> ALL (ARRAY[''latest''::text, ''default''::text, ''unknown''::text]))) AND ((octet_length(qualified_symbol_key) >= 1) AND (octet_length(qualified_symbol_key) <= 512)) AND (qualified_symbol_key ~ ''[^[:space:]]''::text)) IS TRUE))"},{"name":"sr2_symbol_locators_v1_c2","type":"c","definition":"CHECK ((((entry_kind = ''REGULAR_FILE''::text) AND (encoding_id = ''UTF8_STRICT_V1''::text) AND (byte_length <= 524288) AND (byte_start IS NOT NULL) AND (byte_end IS NOT NULL) AND (line_start IS NOT NULL) AND (line_end IS NOT NULL) AND (byte_start >= 0) AND (byte_start < byte_end) AND (byte_end <= byte_length) AND (line_start >= 1) AND (line_start <= line_end) AND (line_end <= line_count) AND (decoding_id = ''UTF8_STRICT_V1''::text)) IS TRUE))"},{"name":"sr2_symbol_locators_v1_c3","type":"c","definition":"CHECK (((locator_id = encode(sha256(convert_to(gov_repo.frame_identity(ARRAY[''GOVIA_SR2_SYMBOL_LOCATOR_V1''::text, (organisation_id)::text, repository_id, snapshot_id, entry_id, source_fingerprint, language_id, parser_id, parser_version, qualified_symbol_key, (byte_start)::text, (byte_end)::text, (line_start)::text, (line_end)::text, decoding_id]), ''UTF8''::name)), ''hex''::text)) IS TRUE))"},{"name":"sr2_symbol_locators_v1_f1","type":"f","definition":"FOREIGN KEY (organisation_id, repository_id, snapshot_id, entry_id, source_fingerprint, entry_kind, byte_length, encoding_id, line_count) REFERENCES gov_repo.sr2_manifest_entries_v1(organisation_id, repository_id, snapshot_id, entry_id, source_fingerprint, entry_kind, byte_length, encoding_id, line_count)"},{"name":"sr2_symbol_locators_v1_pkey","type":"p","definition":"PRIMARY KEY (organisation_id, repository_id, snapshot_id, locator_id)"},{"name":"sr2_symbol_locators_v1_u1","type":"u","definition":"UNIQUE (organisation_id, repository_id, snapshot_id, locator_id, entry_id, source_fingerprint)"}]}'::jsonb THEN RAISE EXCEPTION 'SR2_A2_A1_CATALOG_DRIFT' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE d.defaclrole='postgres'::regrole AND d.defaclobjtype='f'
  AND d.defaclnamespace IN (0,'gov_repo'::regnamespace) AND a.grantee IN (0,'anon'::regrole,'authenticated'::regrole,'service_role'::regrole))
  OR NOT EXISTS(SELECT FROM pg_default_acl WHERE defaclrole='postgres'::regrole AND defaclobjtype='f' AND defaclnamespace=0) THEN
  RAISE EXCEPTION 'SR2_A2_DEFAULT_ACL_DRIFT' USING ERRCODE='55000'; END IF;

 IF EXISTS(SELECT FROM pg_proc WHERE pronamespace='gov_repo'::regnamespace AND proname IN ('sr2_disclosure_head_guard_v1','technical_semantic_context_search_v1'))
  OR EXISTS(SELECT FROM pg_class WHERE relnamespace='gov_repo'::regnamespace AND relname=ANY(ARRAY['sr2_disclosure_profile_heads_v1','sr2_disclosure_profiles_v1','sr2_source_admission_heads_v1','sr2_representations_v1_exact_space_read_idx']::text[])) THEN
  RAISE EXCEPTION 'SR2_A2_OBJECT_CONFLICT' USING ERRCODE='55000'; END IF;
END $a2_preflight$;
