CREATE TABLE gov_repo.sr2_disclosure_profiles_v1 (
 organisation_id uuid NOT NULL,
 repository_id text COLLATE "C" NOT NULL,
 purpose_code text COLLATE "C" NOT NULL,
 disclosure_profile_id text COLLATE "C" NOT NULL,
 disclosure_profile_version text COLLATE "C" NOT NULL,
 admission_recipe_id text COLLATE "C" NOT NULL,
 admission_recipe_version text COLLATE "C" NOT NULL,
 policy_profile_id text COLLATE "C" NOT NULL,
 policy_profile_version text COLLATE "C" NOT NULL,
 handling_recipe_id text COLLATE "C" NOT NULL,
 handling_recipe_version text COLLATE "C" NOT NULL,
 required_projection_schema_version text COLLATE "C" NOT NULL,
 document_recipe text COLLATE "C" NOT NULL,
 profile_fingerprint text COLLATE "C" NOT NULL,
 recorded_at timestamptz NOT NULL,
 CONSTRAINT sr2_disclosure_profiles_v1_pkey PRIMARY KEY
  (organisation_id,repository_id,purpose_code,disclosure_profile_id,disclosure_profile_version),
 CONSTRAINT sr2_disclosure_profiles_v1_f1 FOREIGN KEY (organisation_id,repository_id)
  REFERENCES gov_repo.sr2_repositories_v1 (organisation_id,repository_id) ON UPDATE NO ACTION ON DELETE NO ACTION,
 CONSTRAINT sr2_disclosure_profiles_v1_c1 CHECK (purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'),
 CONSTRAINT sr2_disclosure_profiles_v1_c2 CHECK (
  gov_repo.sr2_list_valid_v1(ARRAY[disclosure_profile_id,disclosure_profile_version,admission_recipe_id,
   admission_recipe_version,policy_profile_id,policy_profile_version,handling_recipe_id,
   handling_recipe_version,required_projection_schema_version],9)
  AND lower(btrim(disclosure_profile_id)) NOT IN ('latest','default','unknown')
  AND lower(btrim(disclosure_profile_version)) NOT IN ('latest','default','unknown')
  AND lower(btrim(admission_recipe_id)) NOT IN ('latest','default','unknown')
  AND lower(btrim(admission_recipe_version)) NOT IN ('latest','default','unknown')
  AND lower(btrim(policy_profile_id)) NOT IN ('latest','default','unknown')
  AND lower(btrim(policy_profile_version)) NOT IN ('latest','default','unknown')
  AND lower(btrim(handling_recipe_id)) NOT IN ('latest','default','unknown')
  AND lower(btrim(handling_recipe_version)) NOT IN ('latest','default','unknown')
  AND lower(btrim(required_projection_schema_version)) NOT IN ('latest','default','unknown')),
 CONSTRAINT sr2_disclosure_profiles_v1_c3 CHECK (document_recipe='GOVIA_TECHNICAL_CONTEXT_V1'),
 CONSTRAINT sr2_disclosure_profiles_v1_c4 CHECK (profile_fingerprint ~ '^[0-9a-f]{64}$'
  AND profile_fingerprint=encode(sha256(convert_to(gov_repo.frame_identity(ARRAY[
   'GOVIA_SR2_DISCLOSURE_PROFILE_V1',organisation_id::text,repository_id,purpose_code,
   disclosure_profile_id,disclosure_profile_version,admission_recipe_id,admission_recipe_version,
   policy_profile_id,policy_profile_version,handling_recipe_id,handling_recipe_version,
   required_projection_schema_version,document_recipe]),'UTF8')),'hex')),
 CONSTRAINT sr2_disclosure_profiles_v1_c5 CHECK (isfinite(recorded_at))
);
ALTER TABLE gov_repo.sr2_disclosure_profiles_v1 OWNER TO postgres;
ALTER TABLE gov_repo.sr2_disclosure_profiles_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE gov_repo.sr2_disclosure_profiles_v1 FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE gov_repo.sr2_disclosure_profiles_v1 IS 'TECHNICAL_DISCLOSURE_CONTROL_NON_GOVERNANCE_AUTHORITY';

CREATE TABLE gov_repo.sr2_disclosure_profile_heads_v1 (
 organisation_id uuid NOT NULL,
 repository_id text COLLATE "C" NOT NULL,
 purpose_code text COLLATE "C" NOT NULL,
 disclosure_profile_id text COLLATE "C" NOT NULL,
 disclosure_profile_version text COLLATE "C" NOT NULL,
 enabled boolean NOT NULL,
 head_revision bigint NOT NULL,
 CONSTRAINT sr2_disclosure_profile_heads_v1_pkey PRIMARY KEY (organisation_id,repository_id,purpose_code),
 CONSTRAINT sr2_disclosure_profile_heads_v1_f1 FOREIGN KEY
  (organisation_id,repository_id,purpose_code,disclosure_profile_id,disclosure_profile_version)
  REFERENCES gov_repo.sr2_disclosure_profiles_v1
  (organisation_id,repository_id,purpose_code,disclosure_profile_id,disclosure_profile_version)
  ON UPDATE NO ACTION ON DELETE NO ACTION,
 CONSTRAINT sr2_disclosure_profile_heads_v1_c1 CHECK (purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'),
 CONSTRAINT sr2_disclosure_profile_heads_v1_c2 CHECK (head_revision>=1)
);
ALTER TABLE gov_repo.sr2_disclosure_profile_heads_v1 OWNER TO postgres;
ALTER TABLE gov_repo.sr2_disclosure_profile_heads_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE gov_repo.sr2_disclosure_profile_heads_v1 FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE gov_repo.sr2_disclosure_profile_heads_v1 IS 'TECHNICAL_DISCLOSURE_CONTROL_NON_GOVERNANCE_AUTHORITY';

CREATE TABLE gov_repo.sr2_source_admission_heads_v1 (
 organisation_id uuid NOT NULL,
 repository_id text COLLATE "C" NOT NULL,
 snapshot_id text COLLATE "C" NOT NULL,
 entry_id text COLLATE "C" NOT NULL,
 purpose_code text COLLATE "C" NOT NULL,
 source_admission_id text COLLATE "C" NOT NULL,
 enabled boolean NOT NULL,
 head_revision bigint NOT NULL,
 CONSTRAINT sr2_source_admission_heads_v1_pkey PRIMARY KEY
  (organisation_id,repository_id,snapshot_id,entry_id,purpose_code),
 CONSTRAINT sr2_source_admission_heads_v1_f1 FOREIGN KEY
  (organisation_id,repository_id,snapshot_id,entry_id,source_admission_id)
  REFERENCES gov_repo.sr2_source_admissions_v1
  (organisation_id,repository_id,snapshot_id,entry_id,source_admission_id)
  ON UPDATE NO ACTION ON DELETE NO ACTION,
 CONSTRAINT sr2_source_admission_heads_v1_c1 CHECK (purpose_code='TECHNICAL_CONTEXT_HYDRATION_V1'),
 CONSTRAINT sr2_source_admission_heads_v1_c2 CHECK (head_revision>=1)
);
ALTER TABLE gov_repo.sr2_source_admission_heads_v1 OWNER TO postgres;
ALTER TABLE gov_repo.sr2_source_admission_heads_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE gov_repo.sr2_source_admission_heads_v1 FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE gov_repo.sr2_source_admission_heads_v1 IS 'TECHNICAL_DISCLOSURE_CONTROL_NON_GOVERNANCE_AUTHORITY';

CREATE FUNCTION gov_repo.sr2_disclosure_head_guard_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER VOLATILE PARALLEL UNSAFE CALLED ON NULL INPUT
SET search_path=pg_catalog,pg_temp AS $head$
BEGIN
 IF TG_WHEN<>'BEFORE' OR TG_LEVEL<>'ROW' OR TG_NARGS<>0 OR TG_OP NOT IN ('INSERT','UPDATE')
  OR TG_RELID NOT IN ('gov_repo.sr2_disclosure_profile_heads_v1'::regclass,
                     'gov_repo.sr2_source_admission_heads_v1'::regclass) THEN
  RAISE EXCEPTION 'SR2_DISCLOSURE_GUARD_ATTACHMENT' USING ERRCODE='55000';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.head_revision IS DISTINCT FROM 1::bigint THEN
   RAISE EXCEPTION 'SR2_DISCLOSURE_INITIAL_REVISION' USING ERRCODE='23514';
  END IF;
 ELSE
  IF NEW.organisation_id IS DISTINCT FROM OLD.organisation_id
   OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
   OR NEW.purpose_code IS DISTINCT FROM OLD.purpose_code THEN
   RAISE EXCEPTION 'SR2_DISCLOSURE_IMMUTABLE_KEY' USING ERRCODE='23514';
  END IF;
  IF OLD.head_revision=9223372036854775807 THEN
   RAISE EXCEPTION 'SR2_DISCLOSURE_REVISION_OVERFLOW' USING ERRCODE='23514';
  END IF;
  IF NEW.head_revision IS DISTINCT FROM OLD.head_revision+1 THEN
   RAISE EXCEPTION 'SR2_DISCLOSURE_REVISION_TRANSITION' USING ERRCODE='23514';
  END IF;
  IF TG_RELID='gov_repo.sr2_disclosure_profile_heads_v1'::regclass THEN
   IF ROW(NEW.disclosure_profile_id,NEW.disclosure_profile_version,NEW.enabled)
     IS NOT DISTINCT FROM ROW(OLD.disclosure_profile_id,OLD.disclosure_profile_version,OLD.enabled) THEN
    RAISE EXCEPTION 'SR2_DISCLOSURE_NO_OP' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.snapshot_id IS DISTINCT FROM OLD.snapshot_id OR NEW.entry_id IS DISTINCT FROM OLD.entry_id THEN
    RAISE EXCEPTION 'SR2_DISCLOSURE_IMMUTABLE_KEY' USING ERRCODE='23514';
   END IF;
   IF ROW(NEW.source_admission_id,NEW.enabled) IS NOT DISTINCT FROM ROW(OLD.source_admission_id,OLD.enabled) THEN
    RAISE EXCEPTION 'SR2_DISCLOSURE_NO_OP' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END
$head$;
ALTER FUNCTION gov_repo.sr2_disclosure_head_guard_v1() OWNER TO postgres;
REVOKE ALL ON FUNCTION gov_repo.sr2_disclosure_head_guard_v1() FROM PUBLIC,anon,authenticated,service_role;

CREATE TRIGGER sr2_disclosure_profiles_v1_immutable BEFORE UPDATE OR DELETE OR TRUNCATE
 ON gov_repo.sr2_disclosure_profiles_v1 FOR EACH STATEMENT EXECUTE FUNCTION gov_repo.sr2_immutable_v1();
ALTER TABLE gov_repo.sr2_disclosure_profiles_v1 ENABLE ALWAYS TRIGGER sr2_disclosure_profiles_v1_immutable;
