pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(gov_repo.frame_identity(ARRAY['GOVIA_SR2_REPRESENTATION_V1',r.organisation_id::text,r.repository_id::text,r.snapshot_id::text,r.subject_id::text,r.projection_id::text,r.projection_schema_version::text,r.projection_fingerprint::text,r.provider_id::text,r.model_id::text,r.model_version::text,r.dimension::text]::text[]), 'UTF8')), 'hex')) IS TRUE)) AND r.projection_admitted_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.capture_observed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.generated_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.indexed_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock) AND r.recorded_at BETWEEN '0001-01-01 UTC'::timestamptz AND (SELECT at FROM acquired_clock)) IS TRUE AS valid_rep
  FROM gov_repo.sr2_representations_v1 r WHERE r.organisation_id=v_org AND r.repository_id=p_repository_id COLLATE "C" AND r.snapshot_id=p_snapshot_id COLLATE "C" AND r.projection_schema_version=p_schema COLLATE "C"
