sion::text]::text[] || ARRAY[cardinality(i.limitations)::text] || i.limitations || ARRAY[i.module_key::text]::text[] || ARRAY[i.module_kind::text]::text[] || ARRAY[i.directory_label::text]::text[] || ARRAY[i.module_name::text]::text[])), 'UTF8')), 'hex')) IS TRUE)) AS valid,coalesce((SELECT sum(octet_length(v)) FROM unnest(i.limitations) v),0)+coalesce(octet_length(i.module_key),0)+coalesce(octet_length(i.directory_label),0)+coalesce(octet_length(i.module_name),0) AS human_bytes,
