ice_name::text]::text[] || ARRAY[i.service_kind::text]::text[] || ARRAY[cardinality(i.capabilities)::text] || i.capabilities)), 'UTF8')), 'hex')) IS TRUE)) AS valid,coalesce((SELECT sum(octet_length(v)) FROM unnest(i.limitations) v),0)+coalesce(octet_length(i.service_key),0)+coalesce(octet_length(i.service_name),0)+coalesce((SELECT sum(octet_length(v)) FROM unnest(i.capabilities) v),0) AS human_bytes,
