BEGIN
 
 SELECT n.nspname INTO STRICT v_ext FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='vector' AND e.extversion='0.8.7';
 IF current_user<>'postgres' OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
  OR EXISTS(SELECT FROM unnest(ARRAY['anon','authenticated','service_role']) role_name WHERE has_schema_privilege(role_name,v_ext,'CREATE')) THEN
  RAISE EXCEPTION 'SR2_A2_UNTRUSTED_BASELINE' USING ERRCODE='55000'; END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object('identity',replace(replace(replace(p.oid::regprocedure::text,quote_ident(v_ext)||'.vector','__vector__.vector'),',vector,',',__vector__.vector,'),'(vector,','(__vector__.vector,'),'owner',pg_get_userbyid(p.proowner),
 'body_sha256',encode(sha256(convert_to(replace(CASE WHEN p.oid=to_regprocedure(format('gov_repo.semantic_context_search_v1(uuid,uuid,bigint,bigint,timestamptz,%I.vector,text,text,text,integer,text,integer,double precision)',v_ext)) THEN replace(p.prosrc,quote_ident(v_ext)||'.','__vector__.') ELSE p.prosrc END,chr(13),''),'UTF8')),'hex'),
 'config',p.proconfig,'acl',p.proacl::text,'definer',p.prosecdef,'volatility',p.provolatile,'parallel',p.proparallel,'result',pg_get_function_result(p.oid),'language',l.lanname,'strict',p.proisstrict,'leakproof',p.proleakproof,'defaults',p.pronargdefaults)
 ORDER BY replace(replace(replace(p.oid::regprocedure::text,quote_ident(v_ext)||'.vector','__vector__.vector'),',vector,',',__vector__.vector,'),'(vector,','(__vector__.vector,') COLLATE "C"),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
