 AND NOT EXISTS(SELECT FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')
 AND NOT EXISTS(SELECT FROM unnest(ARRAY[to_regprocedure('gov_repo.sr2_disclosure_head_guard_v1()'),to_regprocedure(format('gov_repo.technical_semantic_context_search_v1(uuid,uuid,bigint,bigint,timestamptz,text,text,%I.vector,text,text,text,integer,text,text,integer,double precision)',v_ext))]) admitted(oid) WHERE admitted.oid=p.oid)) IS DISTINCT FROM '[{"acl":null,"owner":"postgres","config":["search_path=pg_catalog"],"result":"text","strict":false,"definer":false,"defaults":0,"identity":"auth.email()","language":"sql","parallel":"u","leakproof":false,"volatility":"s","body_sha256":"a1fba090c1512d40d4f7e85383c0db056a1f18effc223ed77d9bc100db50b15e"},{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=pg_catalog"],"result":"void","strict":false,"definer":true,"defaults":0,"identity":"gov_repo.activate_runtime_source(uuid,text,text,boolean,gov_repo.runtime_reference)","language":"plpgsql","parallel":"u","leakproof":false,"volatility":"v","body_sha256":"5aee3317fe12c1b6a7d3a9cc79b96fdc18cf8522760d8294683c504d62b18899"},{"acl":"{govia_runtime_executor=X/govia_runtime_executor,service_role=X/govia_runtime_executor}","owner":"govia_runtime_executor","config":["search_path=pg_catalog, pg_temp"],"result":"TABLE(replay boolean, observation jsonb)","strict":false,"definer":true,"defaults":0,"identity":"gov_repo.admit_runtime_observation(uuid,text,gov_repo.runtime_observations)","language":"plpgsql","parallel":"u","leakproof":false,"volatility":"v","body_sha256":"9b6284dd7ca92f092fa567ff48e9ac3eae33f906c9653e9c4b204c04f1c51a18"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","owner":"postgres","config":["search_path=\"\""],"result":"void","strict":false,"definer":false,"defaults":0,"identity":"gov_repo.advance_mandate_mapping_guards(uuid[])","language":"plpgsql","parallel":"u","leakproof":false,"volatility":"v","body_sha256":"cb5e5fc116c57cb99d8333c7e003e5b0649f63f3e3b939a812e7a81f71283983"},{"acl":"{govia_legacy_read_executor=X/govia_legacy_read_e